
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_gga_x_lv_rpw86_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("gga_x_lv_rpw86", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-4.225971028809775e+00, -4.143048102446868e+00, -4.026909200680398e+00, -3.866148415636911e+00, -3.647354089690797e+00, -3.356741849080179e+00, -2.984047835469060e+00, -2.529752340976734e+00, -2.015737029309605e+00, -1.494205011810573e+00, -1.022414799946616e+00, -6.907905725864049e-01, -5.949998678441386e-01, -4.857192131155337e-01, -3.491287097808505e-01, -2.280670608821532e-01, -1.404871157856309e-01, -6.440532280067596e-02, -2.409551664388320e-02, -6.420109109642971e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


